mockup.css:
.mock-section-edge-bleed-overlap { background: #efeadf; color: #17150f; font-family: var(--f-sans); }
.mock-section-edge-bleed-overlap .shot { position: absolute; left: 33%; right: -9%; top: 7%; bottom: 7%; }
.mock-section-edge-bleed-overlap .overlay { position: absolute; left: 6%; top: 20%; inline-size: 40%; z-index: 3;
  background: #16150f; color: #f3f0e7; padding: 4cqw; display: flex; flex-direction: column; gap: 1.6cqw; }
.mock-section-edge-bleed-overlap .overlay h4 { margin: 0; font-family: var(--f-serif); font-size: 3.6cqw; line-height: 1.08; }
.mock-section-edge-bleed-overlap .overlay p { margin: 0; font-size: 1.4cqw; line-height: 1.5; opacity: .75; }
.mock-section-edge-bleed-overlap .overlay .cta { font-size: 1.2cqw; letter-spacing: .14em; text-transform: uppercase;
  border-bottom: 1px solid; padding-bottom: .5cqw; align-self: flex-start; }
